escenas.animacion:
A.bg('#170608', '#050206', true);
const acc = A.accent || '#FF3D3D';
const E = A.k('emergencia', 1.333), To = A.k('todos', 1.667), S = A.k('suenan', 2.667);
const M = A.k('mismo', 3.333), Au = A.k('aunque', 4.0), Tg = A.k('tengas', 4.667), Sa = A.k('saldo', 5.0);

function waves(x, y, s, ph, a) {
  for (let j = 0; j < 3; j++) {
    const f = ((ph + j / 3) % 1);
    const r = (90 + f * 90) * s;
    ctx.save();
    ctx.globalAlpha = a * (1 - f);
    ctx.strokeStyle = acc; ctx.lineWidth = 7 * s; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.arc(x, y, r, -0.55, 0.55); ctx.stroke();
    ctx.beginPath(); ctx.arc(x, y, r, Math.PI - 0.55, Math.PI + 0.55); ctx.stroke();
    ctx.restore();
  }
}

function phone(x, y, s, on, idx, alpha) {
  if (s <= 0.01 || alpha <= 0.01) return;
  const vib = on > 0.5 ? Math.sin(t * 70 + idx * 0.0) * 5 * s : 0;
  const w = 140 * s, h = 260 * s;
  if (on > 0.5) waves(x, y, s, (t * 1.6) % 1, alpha * 0.9);
  A.with(() => {
    A.rect(x - w / 2, y - h / 2, w, h, { r: 22 * s, fill: '#101018', stroke: '#F4F4F8', lw: 4 * s, glow: on > 0.5 ? 30 : 0 });
    const pulse = 0.65 + 0.35 * Math.sin(t * 16);
    const sw = w - 18 * s, sh = h - 40 * s;
    A.rect(x - sw / 2, y - sh / 2, sw, sh, { r: 12 * s, fill: '#1C1C2A' });
    if (on > 0) {
      A.rect(x - sw / 2, y - sh / 2, sw, sh, { r: 12 * s, fill: acc, alpha: on * pulse });
      ctx.save(); ctx.globalAlpha = on * alpha;
      ctx.fillStyle = '#FFFFFF';
      const ts = 44 * s;
      ctx.beginPath(); ctx.moveTo(x, y - ts - 10 * s); ctx.lineTo(x + ts, y + ts * 0.7 - 10 * s); ctx.lineTo(x - ts, y + ts * 0.7 - 10 * s); ctx.closePath(); ctx.fill();
      ctx.restore();
      A.text('!', x, y + 14 * s, { size: 54 * s, color: acc, weight: 900, align: 'center', alpha: on * alpha });
    } else {
      A.text('12:04', x, y - 20 * s, { size: 34 * s, color: '#8A8AA0', weight: 700, align: 'center', alpha: alpha });
    }
    A.rect(x - 22 * s, y - h / 2 + 10 * s, 44 * s, 8 * s, { r: 4 * s, fill: '#2A2A3A' });
  }, { x: x + vib, y: y, alpha: alpha });
}

// grid
const cols = 5, rows = 3, gx = 190, gy = 210, cy = 800;
const heroOn = A.p(E, 0.12, 'crashIn');
const allOn = A.p(S, 0.12, 'crashIn');
for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
  if (r === 1 && c === 2) continue;
  const x = 540 + (c - 2) * gx, y = cy + (r - 1) * gy;
  const d = Math.hypot(c - 2, r - 1);
  const ap = A.pop(To + 0.08 + d * 0.11, 0.4);
  // sync wave lights a bit brighter at "mismo"
  const waveR = A.p(M, 0.7, 'glide') * 1100;
  const dist = Math.hypot(x - 540, y - cy);
  const hit = A.clamp(1 - Math.abs(waveR - dist) / 120);
  phone(x, y, 0.75 * ap * (1 + hit * 0.12), allOn, r * cols + c, A.clamp(ap));
}

// sync wave ring
if (t > M) {
  const pr = A.p(M, 0.7, 'glide');
  A.circle(540, cy, 40 + pr * 1060, { stroke: acc, lw: 10 * (1 - pr) + 1, alpha: 0.8 * (1 - pr) });
}

// hero phone
let hs = A.lerp(2.0, 2.2, A.clamp(t / Math.max(E, 0.1)));
hs = A.lerp(hs, 0.75, A.p(To, 0.6, 'whip'));
hs = A.lerp(hs, 1.15, A.p(Au, 0.5, 'snapSettle'));
const hy = A.lerp(770, cy, A.p(To, 0.6, 'whip'));
const shk = t > E && t < E + 0.4 ? 14 * (1 - (t - E) / 0.4) : 0;
A.with(() => phone(540, hy, hs, heroOn, 99, 1), { shake: shk });
if (t > E) A.rings(540, hy, E, { count: 3, speed: 600, gap: 0.2, maxR: 520, color: acc, lw: 6, alpha: 0.7 });
A.flash(E, 0.25, 0.35);
A.flash(S, 0.3, 0.45);

// secondary zone
const mA = A.p(M, 0.4, 'softLand') * (1 - A.p(Au - 0.15, 0.25, 'accelExit'));
if (mA > 0) A.label('AL MISMO TIEMPO', 540, 1440, { size: 64, bg: acc, color: '#FFFFFF', scale: A.pop(M, 0.45), alpha: mA });
if (t > Au) {
  const sp = A.p(Au, 0.35, 'softLand');
  const cnt = A.counter(5000, 0, A.p(Au + 0.1, Tg + 0.25 - Au, 'softInOut'), 0);
  A.text('SALDO', 540, 1400, { size: 46, color: '#B8B8C8', weight: 800, align: 'center', alpha: sp });
  A.text('$' + cnt, 540, 1520, { size: 120, color: '#FFFFFF', weight: 900, align: 'center', alpha: sp });
}
if (t > Sa - 0.05) {
  const st = A.pop(Sa - 0.05, 0.4);
  A.with(() => {
    A.label('¡IGUAL SUENA!', 540, 1650, { size: 62, bg: acc, color: '#FFFFFF' });
  }, { x: 540, y: 1650, scale: st, rot: -0.06 });
  A.flash(Sa - 0.05, 0.2, 0.25);
}

const W=A.W, acc=A.accent, RED='#FF3B3B';
A.bg('#0a1222','#05080f',true);
const kSAE=A.k('SAE,',0.667), kSis=A.k('Sistema',1.333), kAle=A.k('Alerta',2.0), kEme=A.k('Emergencia.',2.667);
const kY=A.k('Y',3.0), kFun=A.k('funciona',3.667), kMen=A.k('mensajes',4.333), kTex=A.k('texto.',5.0);
// vibración del teléfono al sonar la alerta
let shake=0;
if(t>kSAE && t<kSAE+0.6) shake=8*(1-(t-kSAE)/0.6);
const px=A.p(kMen,0.35,'crashIn');
if(t>kMen && t<kMen+0.4) shake=Math.max(shake,14*(1-(t-kMen)/0.4));
const ph=A.pop(0,0.5);
A.with(()=>{
  // cuerpo del teléfono
  A.rect(370,470,340,620,{r:50,fill:'#0d1626',stroke:'#ffffff',lw:6});
  A.rect(390,530,300,500,{r:22,fill:'#071020'});
  A.rect(500,494,80,14,{r:7,fill:'#2a3550'});
  A.lib.hatch(ctx,[[370,980],[710,980],[710,1090],[370,1090]],{angle:45,spacing:16,width:1.5,color:'rgba(255,255,255,0.12)'});
  // FASE 1: alerta
  const a1=1-A.p(kY,0.4,'accelExit');
  if(a1>0.01){
    A.rings(540,700,0.2,{count:3,speed:160,gap:0.5,maxR:170,color:acc,lw:5,alpha:0.6*a1});
    const ts=A.pop(0.05,0.5);
    A.with(()=>{
      ctx.beginPath();ctx.moveTo(540,620);ctx.lineTo(625,770);ctx.lineTo(455,770);ctx.closePath();
      ctx.fillStyle=acc;ctx.fill();ctx.lineJoin='round';ctx.lineWidth=10;ctx.strokeStyle=acc;ctx.stroke();
      A.rect(532,660,16,62,{r:8,fill:'#071020'});
      A.circle(540,745,10,{fill:'#071020'});
    },{x:540,y:710,scale:ts,alpha:a1});
    const ss=A.pop(kSAE,0.45);
    if(t>=kSAE) A.with(()=>{
      A.text('SAE',540,900,{size:120,color:'#ffffff',weight:900,align:'center'});
    },{x:540,y:870,scale:ss,alpha:a1});
  }
  // FASE 2: chat SMS
  const p2=A.p(kFun-0.25,0.55,'snapSettle');
  if(p2>0.01){
    const bx=A.lerp(720,410,p2);
    A.with(()=>{
      A.text('Mensajes',540,580,{size:30,color:'#8fa3c4',weight:700,align:'center'});
      A.rect(bx,640,220,110,{r:28,fill:'#24344f'});
      A.text('SMS',bx+110,712,{size:50,color:'#ffffff',weight:900,align:'center'});
      const p3=A.p(kFun+0.15,0.45,'softLand');
      const bx2=A.lerp(720,450,p3);
      A.rect(bx2,790,220,90,{r:28,fill:'#3a4d70',alpha:p3});
      for(let i=0;i<3;i++){
        const b=0.5+0.5*Math.sin(t*9-i*0.9);
        A.circle(bx2+70+i*40,835-b*8,11,{fill:'#ffffff',alpha:p3*(0.5+0.5*b)});
      }
    },{alpha:p2});
  }
  // X roja de impacto
  if(t>=kMen){
    const sc=A.lerp(2.6,1,px);
    A.with(()=>{
      A.line([[430,600],[650,900]],{stroke:RED,lw:34,alpha:1});
      A.line([[650,600],[430,900]],{stroke:RED,lw:34,alpha:1});
    },{x:540,y:750,scale:sc,alpha:px});
  }
},{x:540,y:780,scale:ph,shake:shake});
if(t>=kMen) A.flash(kMen,0.25,0.35);
// Sigla desplegada (zona secundaria)
const dim=A.lerp(1,0.3,A.p(kY,0.4,'softInOut'));
const rows=[['S','istema',kSis,1400],['A','lerta',kAle,1510],['E','mergencia',kEme,1620]];
const showA=(t>=kTex)?1-A.p(kTex,0.3,'accelExit'):1;
rows.forEach(([L,rest,k,y])=>{
  const p=A.p(k-0.05,0.45,'softLand');
  if(p<=0.01) return;
  const off=A.lerp(-60,0,p);
  A.text(L,360+off,y+40,{size:104,color:acc,weight:900,align:'center',alpha:p*dim*showA});
  A.text(rest,420+off,y+30,{size:62,color:'#ffffff',weight:700,align:'left',alpha:p*dim*showA});
});
// Cierre: SAE ≠ SMS
if(t>=kTex){
  const s=A.pop(kTex,0.45);
  A.with(()=>{
    A.text('SAE',360,1580,{size:110,color:acc,weight:900,align:'center'});
    A.text('≠',540,1580,{size:110,color:'#ffffff',weight:900,align:'center'});
    A.text('SMS',720,1580,{size:110,color:RED,weight:900,align:'center'});
  },{x:540,y:1540,scale:s});
}

const W=A.W, H=A.H;
A.bg('#0b1630','#050a18');
const acc=A.accent, RED='#ff3b3b';
const tUno=A.k('uno',1.333), tMil=A.k('millones',3.667), tRed=A.k('red',6.0), tSat=A.k('saturaría',6.667);
const redP=A.p(tRed,0.5,'softInOut');
const sat=A.p(tSat,0.35,'crashIn');
const shake = t>tSat ? 16*(1-A.clamp((t-tSat)/0.7)) : 0;
const TX=540, TY=555;
const m=A.p(tMil,0.75,'whip');
// fill / queue progress (shared)
const lin=A.clamp((t-tMil)/Math.max(0.1,tSat-tMil));
const f=Math.pow(lin,0.55);
const mix=(a,b,p)=>{const pa=[parseInt(a.slice(1,3),16),parseInt(a.slice(3,5),16),parseInt(a.slice(5,7),16)],pb=[parseInt(b.slice(1,3),16),parseInt(b.slice(3,5),16),parseInt(b.slice(5,7),16)];return 'rgb('+pa.map((v,i)=>Math.round(A.lerp(v,pb[i],p))).join(',')+')';};
// slots
const COLS=16, ROWS=8;
const slotPos=(s)=>[150+(s%COLS)*52, 820+Math.floor(s/COLS)*40];
const mapped=[];
for(let i=0;i<12;i++){ mapped.push((1+Math.floor(i/4)*3)*COLS + (2+(i%4)*4)); }
const rest=[]; for(let s=0;s<COLS*ROWS;s++) if(mapped.indexOf(s)<0) rest.push(s);
const rr=A.rand(7);
for(let i=rest.length-1;i>0;i--){ const j=Math.floor(rr()*(i+1)); const tmp=rest[i]; rest[i]=rest[j]; rest[j]=tmp; }
const order=mapped.concat(rest);
const GAP=0.33, FLY=0.3;
const nEnv=Math.max(0,Math.floor((t-tUno)/GAP)+1);
const litAt={};
for(let i=0;i<Math.min(nEnv,order.length);i++){ litAt[order[i]]=tUno+i*GAP+FLY; }
const posOf=(s)=>{
  const mi=mapped.indexOf(s);
  const d=slotPos(s);
  if(mi>=0){
    const ox=270+(mi%4)*180, oy=810+Math.floor(mi/4)*125;
    return [A.lerp(ox,d[0],m),A.lerp(oy,d[1],m),A.lerp(64,22,m),A.lerp(100,34,m)];
  }
  return [d[0],d[1],22,34];
};
const pre=A.clamp((t-(tMil+0.8))/Math.max(0.1,tSat-tMil-0.8));
const phone=(s,x,y,w,h,lit,alpha,sc)=>{
  A.with(()=>{
    A.rect(x-w/2,y-h/2,w,h,{r:w*0.2,fill:'#13213d',stroke:'#cfe0ff',lw:Math.max(2,w*0.05),alpha});
    const redFlash = (t>tSat && lit<0.5) ? (0.5+0.5*Math.sin((t-tSat)*30))*sat : 0;
    let col = lit>0 ? acc : (redFlash>0.3 ? RED : '#22365f');
    if(lit<=0 && t<=tSat && pre>0){
      const rs=A.rand(300+s)();
      if(rs<pre*0.55 && Math.sin(t*(14+rs*10)+s*1.7)>0.25) col = (s%3===0)?'#6b7488':RED;
    }
    A.rect(x-w/2+w*0.12,y-h/2+h*0.1,w*0.76,h*0.72,{r:w*0.08,fill:col,alpha:alpha*(lit>0?1:0.9),glow:lit>0?w*0.4:0});
  },{x,y,scale:sc});
};
A.with(()=>{
  // tower
  const tc = redP>0.5 ? RED : '#e8f0ff';
  A.line([[485,750],[TX,TY+20],[595,750]],{stroke:tc,lw:6});
  A.line([[505,690],[575,690]],{stroke:tc,lw:4});
  A.line([[520,640],[560,640]],{stroke:tc,lw:4});
  A.line([[505,690],[560,640],[575,690]],{stroke:tc,lw:3,alpha:0.7});
  A.circle(TX,TY,14,{fill:redP>0.5?RED:acc,glow:30});
  // network links at "red"
  if(redP>0){
    for(let c=0;c<7;c++){
      const tx=170+c*123;
      A.line([[TX,TY+30],[tx,800]],{stroke:RED,lw:3,alpha:0.55*redP,dash:[10,12],progress:redP});
    }
  }
  // phones
  for(let s=0;s<COLS*ROWS;s++){
    const mi=mapped.indexOf(s);
    let alpha=1, sc=1;
    if(mi<0){
      const d=A.rand(100+s)()*0.9;
      const ap=A.clamp((t-(tMil+0.2+d))/0.2);
      if(ap<=0) continue;
      alpha=ap; sc=A.lerp(0.3,1,ap);
    } else if(t<tUno-0.4){
      const ap=A.p(0.1+mi*0.05,0.4,'snapSettle'); alpha=ap; sc=A.pop(0.1+mi*0.05,0.4);
    }
    const p=posOf(s);
    const la=litAt[s];
    const lit = (la!==undefined && t>=la)?1:0;
    if(lit) sc*=A.pop(la,0.35);
    phone(s,p[0],p[1],p[2],p[3],lit,alpha,sc);
  }
  // envelopes in flight + rings
  for(let i=0;i<Math.min(nEnv,order.length);i++){
    const st=tUno+i*GAP;
    if(t<st || t>st+FLY+0.05) continue;
    A.rings(TX,TY,st,{count:1,speed:260,maxR:70,color:acc,lw:3,alpha:0.7});
    const pr=A.p(st,FLY,'glide');
    const p=posOf(order[i]);
    const x=A.lerp(TX,p[0],pr), y=A.lerp(TY+10,p[1],pr)-Math.sin(pr*Math.PI)*50;
    const ew=A.lerp(40,m>0.5?18:34,pr), eh=ew*0.68;
    A.rect(x-ew/2,y-eh/2,ew,eh,{r:3,fill:'#ffffff',glow:12});
    A.line([[x-ew/2,y-eh/2],[x,y+eh*0.1],[x+ew/2,y-eh/2]],{stroke:acc,lw:2});
  }
  if(t>tUno && t<tMil){
    A.label('SMS',TX+120,TY+40,{size:38,bg:acc,color:'#0b1630',scale:A.pop(tUno-0.3,0.4)});
  }
  // impact
  if(t>tSat){
    A.rings(TX,TY,tSat,{count:3,speed:500,gap:0.12,maxR:150,color:RED,lw:6,alpha:0.8});
    A.label('SATURADA',540,960,{size:96,bg:RED,color:'#ffffff',scale:A.pop(tSat,0.45)});
  }
},{x:540,y:800,shake});
// secondary zone
const sent=Math.min(nEnv,order.length);
A.text('ENVIADOS: '+sent,540,1400,{size:48,color:'#ffffff',weight:'800',align:'center',alpha:A.p(tUno-0.2,0.4,'softLand')});
if(t>tMil){
  const ap=A.p(tMil,0.5,'softLand');
  const bx=160,bw=760,by=1480,bh=64;
  const fc = mix('#FF6B35','#ff3b3b',A.clamp(f*1.1));
  A.with(()=>{
    A.text('CAPACIDAD DE LA RED',540,1462,{size:32,color:'#9fb4dd',weight:'700',align:'center'});
    A.rect(bx,by,bw,bh,{r:14,stroke:f>=0.999?RED:'#cfe0ff',lw:4,fill:'#101d38'});
    A.rect(bx+6,by+6,Math.max(0,(bw-12)*f),bh-12,{r:10,fill:fc,glow:10+20*f});
    A.text(Math.round(f*100)+'%',bx+bw-20,by+bh/2+12,{size:34,color:'#ffffff',weight:'900',align:'right'});
    A.text('EN COLA: '+A.counter(0,3000000,f,0),540,1640,{size:62,color:fc,weight:'900',align:'center'});
  },{alpha:ap,shake:shake*0.6,x:540,y:1550,scale:A.lerp(0.9,1,ap)});
}
A.flash(tSat,0.3,0.45);

const ac = A.accent, RED = '#FF5A6E';
A.bg('#0B1A2E', '#050B16');
const kD = A.k('difusión', 1.0), kA = A.k('antena', 2.0), kNo = A.k('no', 2.333), kTel = A.k('teléfono,', 4.0);
const kTr = A.k('transmite', 4.333), kTo = A.k('todos', 5.667), kZ = A.k('zona,', 7.0), kR = A.k('radio.', 8.0);
const E = { x: 540, y: 670 };
const ZX = 540, ZY = 760, RX = 430, RY = 340;
const SPEED = 330;

// ---- Zona (elipse) ----
if (t > kZ) {
  const pz = A.p(kZ, 0.7, 'glide');
  const pts = [];
  for (let i = 0; i <= 64; i++) { const a = -Math.PI / 2 + i / 64 * Math.PI * 2; pts.push([ZX + Math.cos(a) * RX, ZY + Math.sin(a) * RY]); }
  ctx.save(); ctx.globalAlpha = 0.10 * pz; ctx.fillStyle = ac;
  ctx.beginPath(); ctx.ellipse(ZX, ZY, RX, RY, 0, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  A.line(pts, { stroke: ac, lw: 5, dash: [18, 14], progress: pz, alpha: 0.9 });
}

// ---- Ondas de difusión (recortadas a la zona) ----
if (t > kTr) {
  ctx.save();
  ctx.beginPath(); ctx.ellipse(ZX, ZY, RX, RY, 0, 0, Math.PI * 2); ctx.clip();
  for (let j = 0; j < 7; j++) {
    const r = (t - kTr) * SPEED - j * 150;
    if (r > 5 && r < 720) A.circle(E.x, E.y, r, { stroke: ac, lw: 7, alpha: (1 - r / 720) * 0.85, glow: 12 });
  }
  ctx.restore();
}

// ---- Torre ----
const pT = A.p(0.1, 0.9, 'snapSettle');
const base = 1010;
A.line([[E.x - 70, base], [E.x - 8, E.y + 30]], { stroke: '#DDE8F2', lw: 7, progress: pT });
A.line([[E.x + 70, base], [E.x + 8, E.y + 30]], { stroke: '#DDE8F2', lw: 7, progress: pT });
for (let i = 0; i < 4; i++) {
  const y1 = base - i * 80, y2 = base - (i + 1) * 80;
  const w1 = 70 - i * 15.5, w2 = 70 - (i + 1) * 15.5;
  const pb = A.p(0.3 + i * 0.12, 0.4, 'softLand');
  A.line([[E.x - w1, y1], [E.x + w2, y2]], { stroke: '#8FA6BF', lw: 4, progress: pb });
  A.line([[E.x + w1, y1], [E.x - w2, y2]], { stroke: '#8FA6BF', lw: 4, progress: pb });
}
A.line([[E.x, E.y + 30], [E.x, E.y - 10]], { stroke: '#DDE8F2', lw: 7, progress: pT });
// emisor
const pE = A.pop(kD, 0.5);
const pulse = t > kTr ? 0.5 + 0.5 * Math.sin((t - kTr) * 12) : 0;
A.circle(E.x, E.y - 10, 22 * pE * (1 + 0.15 * pulse), { fill: ac, glow: 30 + 20 * pulse });
if (t > kD && t < kNo + 0.5) A.rings(E.x, E.y - 10, kD, { count: 2, speed: 160, gap: 0.4, maxR: 110, color: ac, lw: 3, alpha: 0.6 });

// ---- Celulares ----
function phone(x, y, lit, s, rot, dim, alpha) {
  A.with(() => {
    A.rect(x - 32, y - 54, 64, 108, { r: 13, fill: '#0E2238', stroke: lit > 0.01 ? ac : (dim ? '#4A5B6E' : '#9FB3C8'), lw: 5, glow: lit * 25 });
    ctx.save(); ctx.globalAlpha = (dim ? 0.35 : 1) * alpha;
    ctx.fillStyle = '#16314F'; ctx.fillRect(x - 23, y - 42, 46, 80);
    if (lit > 0) { ctx.globalAlpha = lit * alpha; ctx.fillStyle = ac; ctx.fillRect(x - 23, y - 42, 46, 80); }
    ctx.restore();
    if (lit > 0.5) A.text('!', x, y + 18, { size: 54, color: '#06121F', weight: 900, align: 'center', alpha: lit });
  }, { x, y, scale: s, rot, alpha });
}
const P = [[230, 560], [850, 560], [170, 790], [910, 790], [250, 1030], [830, 1030], [400, 470], [680, 470]];
// orden de las flechas: alternado
