function bell(x,y,s,color,rot){
  A.with(()=>{
    ctx.fillStyle=color;
    ctx.beginPath();
    ctx.moveTo(x-s*.72,y+s*.45); ctx.lineTo(x+s*.72,y+s*.45);
    ctx.quadraticCurveTo(x+s*.5,y+s*.25,x+s*.5,y-s*.1);
    ctx.quadraticCurveTo(x+s*.5,y-s*.72,x,y-s*.72);
    ctx.quadraticCurveTo(x-s*.5,y-s*.72,x-s*.5,y-s*.1);
    ctx.quadraticCurveTo(x-s*.5,y+s*.25,x-s*.72,y+s*.45);
    ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.arc(x,y+s*.62,s*.16,0,Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(x,y-s*.78,s*.1,0,Math.PI*2); ctx.fill();
  },{x:x,y:y-s*.7,rot:rot||0});
}
function slash(x,y,s,color,p){
  A.line([[x-s*.8,y-s*.8],[x+s*.8,y+s*.8]],{stroke:color,lw:Math.max(4,s*.14),progress:p});
