function arcs(x,y,sc,a,phase){
  if(a<=0.01) return;
  for(let side=-1;side<=1;side+=2){
    for(let i=0;i<3;i++){
      const ph=((t*2.2+phase+i/3)%1);
      const r=(170+ph*120)*sc;
      ctx.save();
      ctx.globalAlpha=a*(1-ph);
      ctx.strokeStyle=i===0?'#ffffff':ac;
      ctx.lineWidth=10*sc*(0.6+a*0.6);
      ctx.lineCap='round';
      ctx.beginPath();
      if(side<0) ctx.arc(x,y,r,Math.PI-0.45,Math.PI+0.45);
      else ctx.arc(x,y,r,-0.45,0.45);
      ctx.stroke(); ctx.restore();
    }
  }
}
